/* =========================================================
   PANEL · HOME DE MÓDULOS (/dashboard)
========================================================= */
/* ── Hero: saludo + estado del día ──
   Dejó de ser un saludo decorativo. Con `has-estado` incorpora una segunda fila
   con lo que pasa hoy y lo que está pendiente, en vez de la tira suelta que
   colgaba debajo del panel. Las tarjetas a cero no se pintan, así que un día sin
   nada el hero vuelve a ser exactamente lo que era. */
.mh-hero {
    display:flex; flex-direction:column;
    background:#fff; border:1px solid #eef2f7; border-radius:22px;
    padding:26px 30px; margin-bottom:26px;
    box-shadow:0 1px 3px rgba(0,0,0,.05), 0 12px 30px -22px rgba(11,31,61,.4);
    position:relative; overflow:hidden;
}
.mh-hero::after { content:''; position:absolute; right:-40px; top:-40px; width:200px; height:200px; border-radius:50%; background:radial-gradient(circle,rgba(66,103,172,.06),transparent 70%); }
.mh-hero__top  { display:flex; align-items:center; justify-content:space-between; gap:24px; }
.mh-hero__left { display:flex; align-items:center; gap:22px; position:relative; z-index:1; }

/* ── Fila de estado ── */
.mh-estado {
    position:relative; z-index:1;
    display:flex; flex-wrap:wrap; gap:12px;
    margin-top:22px; padding-top:20px;
    border-top:1px solid #eef2f7;
}

/* Cada tarjeta: etiqueta pequeña arriba, dato con peso abajo. Es un enlace,
   así que el estado no solo informa: lleva a resolverlo. */
.mh-est {
    --est: #4267ac;
    flex:1 1 190px; min-width:0;
    display:flex; align-items:center; gap:12px;
    padding:12px 16px; border-radius:14px;
    background:color-mix(in srgb, var(--est) 7%, #fff);
    border:1.5px solid color-mix(in srgb, var(--est) 22%, #fff);
    text-decoration:none;
    transition:transform .16s ease, box-shadow .16s ease, border-color .16s ease;

    &:not(.is-static):hover {
        transform:translateY(-2px);
        border-color:var(--est);
        box-shadow:0 12px 24px -14px color-mix(in srgb, var(--est) 90%, transparent);
    }
    &.is-static { cursor:default; }

    &--cumple    { --est: #fc6722; }
    &--notif     { --est: #4285f4; }
    &--cobertura { --est: #8ac926; }
    &--suplente  { --est: #e51022; }
    &--evento    { --est: #aa2296; }
}
.mh-est__ico {
    width:38px; height:38px; flex-shrink:0; border-radius:11px;
    display:grid; place-items:center;
    background:var(--est); color:#fff; font-size:15px;
    box-shadow:0 6px 14px -8px var(--est);
}
.mh-est__avas { display:flex; flex-shrink:0; }
.mh-est__avas .mh-cumple__ava { width:38px; height:38px; font-size:14px; border-width:2px; }
.mh-est__txt   { display:flex; flex-direction:column; gap:1px; min-width:0; }
.mh-est__label {
    font-size:10.5px; font-weight:800; text-transform:uppercase; letter-spacing:.08em;
    color:color-mix(in srgb, var(--est) 78%, #0B1F3D);
    display:flex; align-items:center; gap:6px;
}
.mh-est__dato {
    font-size:14px; font-weight:700; color:#0B1F3D; line-height:1.3;
    overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
}

@media (max-width:720px) {
    .mh-estado { gap:10px; }
    .mh-est { flex:1 1 100%; }
}
.mh-datetile {
    width:118px; height:118px; border-radius:24px; flex-shrink:0;
    background:linear-gradient(150deg,#2e4b8a,#4267ac); color:#fff;
    display:flex; flex-direction:column; align-items:center; justify-content:center; line-height:1;
    box-shadow:0 16px 32px -12px rgba(66,103,172,.65);
}
/* Hay cumpleaños hoy: la fecha principal se tiñe de naranja institucional */
.mh-datetile--cumple {
    background:linear-gradient(150deg,#c74b12,#fc6722);
    box-shadow:0 16px 32px -12px rgba(252,103,34,.7);
}
.mh-datetile__dow { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:1.5px; opacity:.85; }
.mh-datetile__d   { font-size:50px; font-weight:800; margin:4px 0; }
.mh-datetile__mo  { font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:1.5px; opacity:.85; }
.mh-hero__eyebrow { font-size:11px; font-weight:700; letter-spacing:1.5px; text-transform:uppercase; color:#94A3B8; margin-bottom:5px; display:flex; align-items:center; gap:7px; }
.mh-hero__title   { font-size:26px; font-weight:800; color:#0B1F3D; margin:0 0 5px; }
.mh-hero__sub     { font-size:13.5px; color:#64748B; }
.mh-hero__sub strong { color:#4267ac; }
.mh-hero__alex    { width:120px; height:auto; position:relative; z-index:1; flex-shrink:0; filter:drop-shadow(0 12px 22px rgba(11,31,61,.28)); animation:mh-float 3.4s ease-in-out infinite; }
@keyframes mh-float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-8px)} }

/* Avatares de quien cumple. Se solapan para que varios cumpleaños el mismo día
   no empujen el texto fuera de la tarjeta. Los reusa .mh-est__avas en el hero;
   el resto del bloque .mh-cumple desapareció al integrarse en .mh-hero. */
.mh-cumple__ava {
    width:42px; height:42px; border-radius:50%; overflow:hidden;
    display:grid; place-items:center; flex-shrink:0;
    background:linear-gradient(135deg,var(--pal-naranja),var(--pal-ambar));
    color:#fff; font-size:16px; font-weight:800;
    border:2.5px solid #fff; box-shadow:0 4px 10px -4px rgba(11,31,61,.35);

    & + & { margin-left:-12px; }
    img { width:100%; height:100%; object-fit:cover; }
}

.mh-section-label { font-size:12px; font-weight:800; letter-spacing:1.4px; text-transform:uppercase; color:#94A3B8; margin:0 0 16px; display:flex; align-items:center; gap:8px; }

/* ── Módulos (fondo de color completo, contenido en blanco) ── */
.mh-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(285px,1fr)); gap:20px; margin-bottom:34px; }
.mh-card {
    position:relative; display:block; text-decoration:none; border-radius:18px;
    padding:20px 22px; overflow:hidden; color:#fff;
    box-shadow:0 14px 34px -18px rgba(11,31,61,.5);
    transition:transform .22s cubic-bezier(.34,1.56,.64,1), box-shadow .22s;
}
.mh-card::after { content:''; position:absolute; right:-34px; bottom:-34px; width:130px; height:130px; border-radius:50%; background:rgba(255,255,255,.12); transition:transform .3s ease; }
.mh-card:hover { transform:translateY(-6px); box-shadow:0 28px 56px -22px rgba(11,31,61,.6); }
.mh-card:hover::after { transform:scale(1.5); }
.mh-card__num { position:absolute; top:18px; right:20px; font-size:28px; font-weight:800; color:rgba(255,255,255,.22); line-height:1; }
.mh-card__icon { width:46px; height:46px; border-radius:13px; display:grid; place-items:center; font-size:18px; color:#fff; background:rgba(255,255,255,.18); margin-bottom:12px; }
.mh-card__name { font-size:18px; font-weight:800; color:#fff; margin-bottom:4px; }
.mh-card__desc { font-size:12.5px; color:rgba(255,255,255,.82); line-height:1.5; margin-bottom:12px; max-width:92%; }
.mh-card__go   { font-size:13px; font-weight:700; color:#fff; display:inline-flex; align-items:center; gap:7px; }
.mh-card__go i { transition:transform .2s; }
.mh-card:hover .mh-card__go i { transform:translateX(5px); }
/* Paleta institucional recorrida en orden cromático arrancando en el cyan.
   El color lo asigna la POSICIÓN de la tarjeta (ver views/blog/home.php), no el módulo:
   así la primera tarjeta visible es siempre cyan, tenga el usuario 2 módulos u 8.
   El primer tono de cada degradado es el color base oscurecido ~18 %. */
.mh-card--c1  { background:linear-gradient(145deg,#2b8d95 0%,#46bdc6 100%); } /* cyan          */
.mh-card--c2  { background:linear-gradient(145deg,#1f5cc0 0%,#4285f4 100%); } /* azul          */
.mh-card--c3  { background:linear-gradient(145deg,#2f4b7d 0%,#4267ac 100%); } /* azul oscuro   */
.mh-card--c4  { background:linear-gradient(145deg,#75156a 0%,#aa2296 100%); } /* morado        */
.mh-card--c5  { background:linear-gradient(145deg,#a80440 0%,#ea075a 100%); } /* rosa          */
.mh-card--c6  { background:linear-gradient(145deg,#a80c1a 0%,#e51022 100%); } /* rojo          */
.mh-card--c7  { background:linear-gradient(145deg,#c74b12 0%,#fc6722 100%); } /* naranja       */
.mh-card--c8  { background:linear-gradient(145deg,#b88200 0%,#f5b400 100%); } /* amarillo      */
.mh-card--c9  { background:linear-gradient(145deg,#62911a 0%,#8ac926 100%); } /* lima          */
.mh-card--c10 { background:linear-gradient(145deg,#22773a 0%,#34a853 100%); } /* verde         */

/* ── Categorías del home ── */
.mh-cat + .mh-cat { margin-top:6px; }
.mh-cat .mh-grid  { margin-bottom:30px; }

/* ── Calendario + cumpleaños ──
   Las dos cajas deben medir lo mismo. La altura la manda el calendario, cuyas
   celdas son cuadradas (aspect-ratio:1 en .bilbao-cal__cell), así que depende del
   ancho de la columna y no se puede fijar a mano: antes .mh-bday-list llevaba un
   min-height:298px que solo cuadraba a un ancho concreto.
   Solución: `stretch` en la fila y cadena flex hasta el paginador, que queda
   anclado abajo con margin-top:auto (el mismo patrón que .cb-wrap en Cumpleaños). */
.mh-cal-row { display:grid; grid-template-columns:1.35fr 1fr; gap:20px; align-items:stretch; }
/* Sin módulo Usuarios no hay lista de cumpleaños: el calendario ocupa el ancho */
.mh-cal-row--solo { grid-template-columns:minmax(0,720px); }
.mh-panel { background:#fff; border:1px solid #eef2f7; border-radius:20px; box-shadow:0 1px 3px rgba(0,0,0,.06); overflow:hidden; display:flex; flex-direction:column; min-height:0; }
.mh-panel__head { padding:20px 22px 4px; flex-shrink:0; }
.mh-panel__title{ font-size:14px; font-weight:800; color:#0B1F3D; display:flex; align-items:center; gap:8px; }
.mh-panel__title i { color:#fc6722; }
.mh-panel__sub  { font-size:11px; color:#94A3B8; margin-top:3px; }
.mh-panel__body { padding:18px 22px 20px; flex:1; display:flex; flex-direction:column; min-height:0; }
/* Sin `justify-content:space-between`: repartía las filas por todo el alto de la
   columna y dejaba huecos enormes entre registros. Ahora se apilan con un gap
   fijo y es blog-home.js quien mide cuántas caben y ajusta `data-pager-per`,
   así que la lista llena la columna sin separar lo que no debe ir separado. */
.mh-bday-list { display:flex; flex-direction:column; gap:6px; flex:1; min-height:0; }
.mh-bday-item { display:flex; align-items:center; gap:12px; padding:9px 10px; border-radius:12px; transition:background .15s; }
.mh-bday-item:hover { background:#f8fafc; }
.mh-bday-item.is-today { background:#fff1e6; }
.mh-bday-item.is-hidden { display:none; }
.mh-bday-ava { width:38px; height:38px; border-radius:50%; background:linear-gradient(135deg,#fc6722,#f5b400); color:#fff; font-weight:800; display:grid; place-items:center; font-size:15px; flex-shrink:0; overflow:hidden; }
.mh-bday-ava img { width:100%; height:100%; object-fit:cover; }
.mh-bday-name { font-size:13px; font-weight:700; color:#1E293B; }
.mh-bday-date { font-size:11px; color:#94A3B8; }
.mh-bday-chip { margin-left:auto; font-size:11px; font-weight:700; color:#fc6722; background:#fff1e6; padding:4px 10px; border-radius:20px; white-space:nowrap; }
.mh-bday-chip--today { background:#fc6722; color:#fff; }
.mh-pager { display:flex; align-items:center; justify-content:space-between; padding:12px 22px 18px; border-top:1px solid #f1f5f9; margin-top:auto; flex-shrink:0; }
.mh-pager__info { font-size:12px; color:#94A3B8; font-weight:600; }
.mh-pager__btns { display:flex; gap:6px; }
.mh-pager__btn { width:32px; height:32px; border-radius:8px; border:1px solid #e2e8f0; background:#fff; color:#64748b; cursor:pointer; display:grid; place-items:center; font-size:12px; transition:.15s; }
.mh-pager__btn:hover:not(:disabled) { background:#f1f5f9; color:#0B1F3D; }
.mh-pager__btn:disabled { opacity:.4; cursor:default; }
.mh-empty { text-align:center; padding:30px 16px; color:#94A3B8; font-size:13px; }

/* ── Próximos eventos (bajo el calendario) ──
   El calendario marca los días, pero sin pasar el ratón no dice qué pasa en ellos.
   El color del tile de fecha lo hereda del tipo de evento, igual que la leyenda. */
.mh-next { margin-top:18px; padding-top:16px; border-top:1px solid #f1f5f9; }
.mh-next__label { font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:.07em; color:#94A3B8; display:flex; align-items:center; gap:7px; margin-bottom:10px; }
.mh-next__label i { color:#fc6722; }
.mh-next__list { display:flex; flex-direction:column; gap:5px; }
.mh-next__item { display:flex; align-items:center; gap:12px; padding:8px 10px; border-radius:12px; transition:background .15s; }
.mh-next__item:hover { background:#f8fafc; }
.mh-next__item.is-today { background:#fff1e6; }
.mh-next__item.is-hidden { display:none; }
.mh-next__date {
    flex-shrink:0; width:42px; padding:5px 0; border-radius:10px; text-align:center; line-height:1.05;
    background:#eef2f7; color:#475569;
    strong { display:block; font-size:15px; font-weight:800; }
    small  { display:block; font-size:9.5px; font-weight:700; text-transform:uppercase; letter-spacing:.04em; opacity:.85; }
}
/* Mismos tipos que Evento::TIPO_LABEL y la leyenda del calendario */
.mh-next__date[data-type="festivo"]    { background:#ffe9ec; color:#e51022; }
.mh-next__date[data-type="evento"]     { background:#e8f0fb; color:#4285f4; }
.mh-next__date[data-type="junta"]      { background:#f8e7f5; color:#aa2296; }
.mh-next__date[data-type="entrega"]    { background:#eaf7e2; color:#57a11a; }
.mh-next__date[data-type="suspension"] { background:#fff3e0; color:#d1690f; }
.mh-next__body  { min-width:0; flex:1; }
.mh-next__title { font-size:13px; font-weight:700; color:#1E293B; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.mh-next__meta  { font-size:11px; color:#94A3B8; }
.mh-next__chip  { margin-left:auto; font-size:11px; font-weight:700; color:#fff; background:#fc6722; padding:4px 10px; border-radius:20px; white-space:nowrap; }
.mh-next .mh-pager { padding:10px 0 0; margin-top:10px; }

/* En una columna las alturas vuelven a ser naturales: igualarlas no aporta nada */
@media (max-width:1050px){
    .mh-cal-row   { grid-template-columns:1fr; align-items:start; }
    .mh-bday-list { flex:none; justify-content:flex-start; }
}
@media (max-width:640px){ .mh-hero{flex-direction:column; align-items:flex-start;} .mh-hero__alex{align-self:center;} }
